    private static readonly string[] Roles={"melody","chords","bass","drums","pad"};
    private static Variant Get(Settings d,string key,Variant fallback=default)=>d.TryGetValue(new StringName(key),out var value)?value:fallback;
    private static Settings SettingsFor(Control o)=>o.Get("_settings").AsGodotDictionary();
    private static GArray Layout(Control o)=>o.Get("_layout").AsGodotArray();
    public void setup(Control o,Settings settings,GArray sections)
    {
        o.Set("_settings",settings.Duplicate(true));o.Set("_layout",Get(settings,"section_layout",sections).AsGodotArray().Duplicate(true));o.AddChild(new Label{Text="Role instruments"});var row=new HFlowContainer();o.AddChild(row);using var instruments=new AudioInstrumentOperations();var presets=instruments.presets();
        foreach(string role in Roles)
