            foreach(var preset in presets){choice.AddItem(preset["label"].AsString());choice.SetItemMetadata(choice.ItemCount-1,preset["id"].AsString());if(preset["id"].AsString()==id)choice.Select(choice.ItemCount-1);}
            choice.ItemSelected+=index=>{var state=SettingsFor(o);var values=Get(state,"instruments",new Settings()).AsGodotDictionary().Duplicate(true);string selected=choice.GetItemMetadata((int)index).AsString();if(selected.Length==0)values.Remove(role);else{using var patches=new AudioInstrumentOperations();values[role]=patches.default_instrument(selected);}state["instruments"]=values;};o.Get("role_controls").AsGodotDictionary()[role]=choice;
        }
        o.AddChild(new Label{Text="Section names (comma separated)"});var input=new LineEdit{Name="SectionStructure",PlaceholderText="Intro, Verse, Chorus, Outro"};o.AddChild(input);o.Set("structure_input",input);var names=new System.Collections.Generic.List<string>();foreach(var raw in Get(SettingsFor(o),"structure",new GArray()).AsGodotArray())names.Add(raw.VariantType==Variant.Type.Dictionary?Get(raw.AsGodotDictionary(),"name","Section").AsString():raw.AsString());input.Text=string.Join(", ",names);
        var toggle=new CheckBox{Text="Use exact section positions and lengths (quarter-note beats)",ButtonPressed=Layout(o).Count>0};o.AddChild(toggle);o.Set("layout_toggle",toggle);var rows=new VBoxContainer();o.AddChild(rows);o.Set("section_rows",rows);rebuild_rows(o);var add=new Button{Text="Add section"};o.AddChild(add);add.Pressed+=()=>add_section(o);o.AddChild(new Label{Text="Regeneration preserves other parts, source windows and automation. Missing samples leave the document unchanged.",AutowrapMode=TextServer.AutowrapMode.WordSmart});
    }
    public void add_section(Control o){double end=0;var layout=Layout(o);foreach(var raw in layout){var item=raw.AsGodotDictionary();end=Math.Max(end,item["start"].AsDouble()+item["duration"].AsDouble());}using var crypto=new Crypto();layout.Add(new Settings{["id"]=Convert.ToHexString(crypto.GenerateRandomBytes(16)).ToLowerInvariant(),["name"]="Section "+(layout.Count+1),["start"]=end,["duration"]=4.0});o.Get("layout_toggle").As<CheckBox>().ButtonPressed=true;rebuild_rows(o);}
    private static void Spin(Node parent,string label,double value,double low,double high,Action<double> change){parent.AddChild(new Label{Text=label});var spin=new SpinBox{MinValue=low,MaxValue=high,Step=.25,Value=value};parent.AddChild(spin);spin.ValueChanged+=v=>change(v);}
    public void rebuild_rows(Control o)
    {
        var host=o.Get("section_rows").As<VBoxContainer>();foreach(var child in host.GetChildren()){host.RemoveChild(child);child.QueueFree();}var layout=Layout(o);
        for(int i=0;i<layout.Count;++i){int index=i;var item=layout[i].AsGodotDictionary();var row=new HFlowContainer();host.AddChild(row);var label=new LineEdit{Text=Get(item,"name","Section").AsString(),CustomMinimumSize=new Vector2(120,0)};row.AddChild(label);label.TextChanged+=value=>item["name"]=value;Spin(row,"Start",Get(item,"start",0).AsDouble(),0,2048,value=>item["start"]=value);Spin(row,"Length",Get(item,"duration",4).AsDouble(),.25,1024,value=>item["duration"]=value);var remove=new Button{Text="Remove"};row.AddChild(remove);remove.Pressed+=()=>{Layout(o).RemoveAt(index);rebuild_rows(o);};}
    }
    public Settings settings_copy(Control o)
    {
        var result=new Settings{["instruments"]=Get(SettingsFor(o),"instruments",new Settings()).AsGodotDictionary().Duplicate(true)};var names=new GArray();foreach(string raw in o.Get("structure_input").As<LineEdit>().Text.Split(',',StringSplitOptions.RemoveEmptyEntries)){string name=raw.Trim();if(name.Length>0)names.Add(name[..Math.Min(name.Length,128)]);}if(names.Count>0)result["structure"]=names;if(o.Get("layout_toggle").As<CheckBox>().ButtonPressed&&Layout(o).Count>0)result["section_layout"]=Layout(o).Duplicate(true);return result;
    }
    public Settings snapshot_arrangement(GodotObject document)
    {
        var parts=new GArray();var previous=new Settings{["settings"]=document.Get("composer_settings").AsGodotDictionary().Duplicate(true),["sections"]=document.Get("sections").AsGodotArray().Duplicate(true),["chords"]=document.Get("chords").AsGodotArray().Duplicate(true),["parts"]=parts};using var edits=new AudioEditSessionOperations();
        foreach(var raw in document.Get("clips").AsGodotArray())
        {
            var clip=raw.AsGodotObject();var actor=document.Call("actor_for_clip",clip.Get("id")).AsGodotObject();if(actor==null)continue;var values=actor.Get("values").AsGodotDictionary();if(!values.ContainsKey(new StringName("composer_role")))continue;double beats=Get(values,"pattern_beats",Get(values,"source_duration",0).AsDouble()*edits.note_source_tempo(actor,document)/60).AsDouble();var part=new Settings{["id"]=Get(values,"composer_part_id",""),["role"]=values[new StringName("composer_role")],["notes"]=Get(values,"notes",new GArray()).AsGodotArray().Duplicate(true),["instrument"]=Get(values,"instrument",new Settings()).AsGodotDictionary().Duplicate(true),["automation"]=Get(values,"automation",new Settings()).AsGodotDictionary().Duplicate(true),["step_settings"]=Get(values,"step_settings",new Settings()).AsGodotDictionary().Duplicate(true),["pattern_beats"]=beats,["_actor_id"]=actor.Get("id"),["_clip_id"]=clip.Get("id")};parts.Add(part);
            if(values.ContainsKey(new StringName("drum_instances"))){var patterns=new GArray();var definitions=Get(values,"drum_patterns",new Settings()).AsGodotDictionary();foreach(var instanceRaw in values[new StringName("drum_instances")].AsGodotArray()){var instance=instanceRaw.AsGodotDictionary();var pattern=Get(definitions,instance["pattern_id"].AsString(),new Settings()).AsGodotDictionary().Duplicate(true);pattern["id"]=instance["id"];pattern["start"]=instance["start"];pattern["section_id"]=Get(instance,"section_id","");patterns.Add(pattern);}part["patterns"]=patterns;}
        }
        return previous;
    }
    public Settings render_arrangement(Settings config,Settings previous,string role,string sectionId,RefCounted? job,int rate)
    {
        Settings Error(string error)=>new Settings{["error"]=error};bool partial=role.Length>0||sectionId.Length>0;if(partial&&Get(previous,"parts",new GArray()).AsGodotArray().Count==0)return Error("There is no generated arrangement to regenerate.");bool sectionFound=sectionId.Length==0;foreach(var raw in Get(previous,"sections",new GArray()).AsGodotArray())if(raw.AsGodotDictionary()["id"].AsString()==sectionId)sectionFound=true;if(!sectionFound)return Error("The selected arrangement section no longer exists.");if(role.Length>0&&Array.IndexOf(Roles,role)<0)return Error("Unknown composer role.");
        using var composer=new AudioComposerOperations();var arrangement=partial?composer.regenerate(config,previous,role,sectionId):composer.generate(config);var outputs=new GArray();var parts=arrangement["parts"].AsGodotArray();using var instruments=new AudioInstrumentOperations();using var steps=new AudioStepControlOperations();using var cache=new AudioSourceCacheOperations();var arrangementSettings=arrangement["settings"].AsGodotDictionary();double bpm=arrangementSettings["tempo"].AsDouble();
        for(int i=0;i<parts.Count;++i)
        {
            if(job!=null&&job.Call("is_cancelled").AsBool())return Error("Cancelled");var part=parts[i].AsGodotDictionary();string partRole=part["role"].AsString();if(role.Length>0&&partRole!=role)continue;job?.Call("update",(double)i/parts.Count,"Rendering "+partRole);var overrides=Get(config,"instruments",new Settings()).AsGodotDictionary();if(partial&&overrides.TryGetValue(partRole,out var chosen)){var instrument=chosen.VariantType==Variant.Type.Dictionary?chosen.AsGodotDictionary().Duplicate(true):instruments.default_instrument(chosen.AsString());part["instrument"]=instrument;var choices=Get(arrangementSettings,"instruments",new Settings()).AsGodotDictionary().Duplicate(true);choices[partRole]=instrument.Duplicate(true);arrangementSettings["instruments"]=choices;}
            var stream=instruments.render_notes(steps.render_copy(part["notes"].AsGodotArray(),Get(part,"step_settings",new Settings()).AsGodotDictionary(),part["instrument"].AsGodotDictionary()),part["instrument"].AsGodotDictionary(),bpm,rate,job,new GArray(),1);if(stream==null)return Error("Could not render "+partRole+". Check required samples and the 300-second render limit; no changes were applied.");double beats=Get(part,"pattern_beats",arrangementSettings["duration"].AsDouble()*bpm/60).AsDouble();foreach(var raw in part["notes"].AsGodotArray()){var note=raw.AsGodotDictionary();beats=Math.Max(beats,Get(note,"start",0).AsDouble()+Get(note,"duration",0).AsDouble());}if(beats*60/bpm>300)return Error("The arrangement exceeds the 300-second render limit; no changes were applied.");stream=cache.fit_pattern(stream,beats*60/bpm);if(stream==null)return Error("The arrangement source could not be fitted; no changes were applied.");part["pattern_beats"]=beats;outputs.Add(new Settings{["part"]=part,["stream"]=stream});
        }
