    }
    public string apply_rendered(RefCounted session,Settings data)
    {
        if(Get(data,"error","").AsString().Length>0)return data["error"].AsString();if(Get(data,"arrangement").VariantType!=Variant.Type.Dictionary||Get(data,"outputs").VariantType!=Variant.Type.Array)return "The composition result is incomplete.";var arrangement=data["arrangement"].AsGodotDictionary();var operations=new GArray();var document=session.Get("document").AsGodotObject();using var edits=new AudioEditSessionOperations();
        foreach(var raw in data["outputs"].AsGodotArray())
