            if(part.ContainsKey("_clip_id")){string id=part["_clip_id"].AsString();var clip=document.Call("clip_for_id",id).AsGodotObject();var actor=document.Call("actor_for_clip",id).AsGodotObject();if(clip==null||actor==null||actor.Get("id").AsString()!=Get(part,"_actor_id","").AsString())return "A generated source changed; regenerate again.";targets.Add(clip.Get("id"));}
            else foreach(var clipRaw in document.Get("clips").AsGodotArray()){var clip=clipRaw.AsGodotObject();var actor=document.Call("actor_for_clip",clip.Get("id")).AsGodotObject();if(actor!=null&&Get(actor.Get("values").AsGodotDictionary(),"composer_role","").AsString()==part["role"].AsString())targets.Add(clip.Get("id"));}
            foreach(var id in targets)if(!edits.can_edit(session,id.AsString()))return "A generated clip is locked or frozen; the arrangement was not changed.";operations.Add(new Settings{["part"]=part,["stream"]=output["stream"],["targets"]=targets});
        }
        if(operations.Count==0)return "The composition result has no sources.";var applied=new GArray();data["applied_clip_ids"]=applied;bool nested=session.Get("_before").VariantType!=Variant.Type.Nil;edits.begin(session,"Generate editable arrangement");var settings=arrangement["settings"].AsGodotDictionary();
        if(document.Get("clips").AsGodotArray().Count==0&&document.Get("tempo_points").AsGodotArray().Count==0&&document.Get("meter_points").AsGodotArray().Count==0&&document.Get("note_base_tempo").AsDouble()==0)document.Set("tempo",settings["tempo"].AsDouble());document.Set("key",settings["key"].AsInt32());document.Set("scale",settings["scale"].AsString());var saved=settings.Duplicate(true);document.Set("composer_settings",saved);var sections=document.Get("sections").AsGodotArray();sections.Clear();foreach(var section in arrangement["sections"].AsGodotArray())sections.Add(section);document.Set("chords",arrangement["chords"].AsGodotArray().Duplicate(true));if(arrangement.ContainsKey("last_regeneration"))saved["last_regeneration"]=arrangement["last_regeneration"].AsGodotDictionary().Duplicate(true);
