            if(targets.Count==0){var track=document.Call("add_track",part["role"].AsString().Capitalize(),"instrument").AsGodotDictionary();track["instrument"]=part["instrument"].AsGodotDictionary().Duplicate(true);track["volume_db"]=-3;var clip=document.Call("insert_source",stream,track["id"].AsString(),0.0,part["role"].AsString().Capitalize()).AsGodotObject();if(clip==null){edits.cancel(session);applied.Clear();return "A composer source could not be inserted; the arrangement was not changed.";}targets.Add(clip.Get("id"));}
            foreach(var id in targets)
            {
                var clip=document.Call("clip_for_id",id).AsGodotObject();var actor=document.Call("actor_for_clip",id).AsGodotObject();var values=actor.Get("values").AsGodotDictionary();values[new StringName("source_bpm")]=settings["tempo"].AsDouble();var signature=Get(settings,"time_signature",new GArray{4,4}).AsGodotArray();values[new StringName("source_meter")]=new GArray{signature[0].AsInt32(),signature[1].AsInt32()};values[new StringName("notes")]=part["notes"].AsGodotArray().Duplicate(true);values[new StringName("instrument")]=part["instrument"].AsGodotDictionary().Duplicate(true);values[new StringName("composer_role")]=part["role"];values[new StringName("composer_part_id")]=part["id"];values[new StringName("pattern_beats")]=part["pattern_beats"].AsDouble();
                if(part["role"].AsString()=="drums"&&Get(part,"patterns",new GArray()).AsGodotArray().Count>0){var definitions=linked.from_part(part,signature);values[new StringName("drum_patterns")]=definitions["definitions"];values[new StringName("drum_instances")]=definitions["instances"];linked.sync(actor);}else{values.Remove(new StringName("drum_patterns"));values.Remove(new StringName("drum_instances"));}if(part.ContainsKey("step_settings"))values[new StringName("step_settings")]=part["step_settings"].AsGodotDictionary().Duplicate(true);else if(!Get(data,"partial",false).AsBool())values.Remove(new StringName("step_settings"));edits.apply_note_render(clip,actor,stream,"");applied.Add(clip.Get("id"));
            }
        }
